import Foundation

// MARK: - Bundled catalog (Resources/appdata.json, generated by tools/build_data.py)

struct Ingredient: Codable, Identifiable {
    let id: String
    let name: String
    let category: String   // protein | sayur | bumbu | misc
    let unit: String
    let pantry: Bool?
}

struct RecipeIngredient: Codable, Hashable {
    let id: String
    let qty: Double?
    let note: String?
}

struct Recipe: Codable, Identifiable {
    let id: String
    let name: String
    let type: String       // main | side | kid
    let timeMinutes: Int
    let servings: Int
    let ingredients: [RecipeIngredient]
    let steps: [String]
}

struct MainMenu: Codable, Identifiable {
    let id: String
    let name: String
    let source: String     // user | online
    let defaultSideId: String
    let kidFriendly: Bool
}

struct SideMenu: Codable, Identifiable {
    let id: String
    let name: String
}

struct KidMenu: Codable, Identifiable {
    let id: String
    let name: String
}

struct Menus: Codable {
    let mains: [MainMenu]
    let sides: [SideMenu]
    let kids: [KidMenu]
    let favorites: [String]
}

struct AppData: Codable {
    let ingredients: [Ingredient]
    let menus: Menus
    let recipes: [String: Recipe]
}

/// Read-only lookup tables built once from the bundled JSON.
final class Catalog {
    static let shared = Catalog()

    let data: AppData
    let ingredients: [String: Ingredient]
    let mains: [String: MainMenu]
    let sides: [String: SideMenu]
    let kids: [String: KidMenu]

    private init() {
        guard let url = Bundle.module.url(forResource: "appdata", withExtension: "json"),
              let raw = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(AppData.self, from: raw) else {
            fatalError("Resources/appdata.json tidak ditemukan atau rusak. Jalankan: python tools/build_data.py")
        }
        data = decoded
        ingredients = Dictionary(uniqueKeysWithValues: decoded.ingredients.map { ($0.id, $0) })
        mains = Dictionary(uniqueKeysWithValues: decoded.menus.mains.map { ($0.id, $0) })
        sides = Dictionary(uniqueKeysWithValues: decoded.menus.sides.map { ($0.id, $0) })
        kids = Dictionary(uniqueKeysWithValues: decoded.menus.kids.map { ($0.id, $0) })
    }

    func name(_ id: String) -> String {
        mains[id]?.name ?? sides[id]?.name ?? kids[id]?.name ?? data.recipes[id]?.name ?? id
    }

    func recipe(_ id: String) -> Recipe? { data.recipes[id] }
}

// MARK: - User state (saved to disk)

struct DayPlan: Codable, Identifiable, Equatable {
    var id = UUID()
    var mainId: String
    var sideId: String
    var kidId: String?      // nil = anak ikut menu dewasa
    var done = false
}

struct WeekPlan: Codable {
    var weekStart: Date
    var days: [DayPlan]
}

struct SavedState: Codable {
    var plan: WeekPlan?
    var shopping: [String: Bool] = [:]       // ingredientId -> sudah dibeli / sudah ada
    var favorites: [String] = []             // "mainId|sideId"
    var kidOverrides: [String: Bool] = [:]   // mainId -> ramah anak (tanda dari pengguna)
    var preferFav = true
}

/// A day while the user is still choosing (step 1 of the generate flow).
struct DraftDay: Identifiable, Equatable {
    let id = UUID()
    var mainId: String
    var sideId: String
    var kidMenuId: String
}

/// One menu that uses a shopping item (shown when the item is expanded).
struct ShoppingUsage: Hashable {
    let day: String
    let dish: String
    let role: String   // Utama | Pendamping | Anak
    let qty: String
}

struct ShoppingItem: Identifiable {
    let id: String
    let name: String
    let qty: String
    let use: String
    let pantry: Bool
    let usages: [ShoppingUsage]
}

struct ShoppingCategory: Identifiable {
    let id: String
    let label: String
    let items: [ShoppingItem]
}

// MARK: - Formatting helpers

enum Fmt {
    static let dayNames = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"]
    static let dayShort = ["SEN", "SEL", "RAB", "KAM", "JUM", "SAB", "MIN"]
    static let dayLabel = ["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"]
    static let months = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"]
    struct Category: Hashable, Identifiable {
        let id: String
        let label: String
    }
    static let categories: [Category] = [
        Category(id: "protein", label: "Protein"),
        Category(id: "sayur", label: "Sayur"),
        Category(id: "bumbu", label: "Bumbu"),
        Category(id: "misc", label: "Misc")
    ]

    static var calendar: Calendar {
        var c = Calendar(identifier: .gregorian)
        c.firstWeekday = 2
        return c
    }

    /// Today if it is Monday, otherwise next Monday.
    static func upcomingMonday(from now: Date = Date()) -> Date {
        let cal = calendar
        let today = cal.startOfDay(for: now)
        let weekday = cal.component(.weekday, from: today)   // 1 = Sunday … 2 = Monday
        let offset = weekday == 2 ? 0 : (9 - weekday) % 7
        return cal.date(byAdding: .day, value: offset, to: today) ?? today
    }

    static func dates(from start: Date) -> [Date] {
        (0..<7).compactMap { calendar.date(byAdding: .day, value: $0, to: start) }
    }

    static func day(_ date: Date) -> Int { calendar.component(.day, from: date) }

    static func month(_ date: Date) -> String { months[calendar.component(.month, from: date) - 1] }

    static func range(_ start: Date) -> String {
        let ds = dates(from: start)
        let a = ds[0], b = ds[6]
        let year = calendar.component(.year, from: b)
        if month(a) == month(b) { return "\(day(a))–\(day(b)) \(month(b)) \(year)" }
        return "\(day(a)) \(month(a)) – \(day(b)) \(month(b)) \(year)"
    }

    static func todayIndex(_ start: Date) -> Int? {
        let today = calendar.startOfDay(for: Date())
        return dates(from: start).firstIndex { calendar.isDate($0, inSameDayAs: today) }
    }

    static func qty(_ q: Double?, unit: String) -> String {
        guard let q else { return "secukupnya" }
        if unit == "g" && q >= 1000 { return number((q / 100).rounded() / 10) + " kg" }
        if unit == "ml" && q >= 1000 { return number((q / 100).rounded() / 10) + " liter" }
        if unit == "g" || unit == "ml" { return "\(Int(q.rounded())) \(unit)" }
        return number(q) + " " + unit
    }

    static func number(_ n: Double) -> String {
        let whole = floor(n)
        let frac = ((n - whole) * 100).rounded() / 100
        let symbols: [Double: String] = [0.25: "¼", 0.5: "½", 0.75: "¾"]
        if let s = symbols[frac] { return whole > 0 ? "\(Int(whole)) \(s)" : s }
        let r = (n * 10).rounded() / 10
        return r == r.rounded() ? "\(Int(r))" : String(format: "%.1f", r).replacingOccurrences(of: ".", with: ",")
    }
}
